const courses = rawHighSchoolIndex.courses.map((course) => ({
  ...course,
  entityId: course.courseId,
})) as readonly HighSchoolCourse[];
const formalResources = rawHighSchoolIndex.resources.map((resource) => ({
  ...resource,
  entityId: resource.resourceId,
})) as readonly HighSchoolFormalResource[];

export const HIGH_SCHOOL_COURSE_INDEX: HighSchoolIndex = {
  courses,
  formalResources,
  publishedResourceIds: formalResources.map((resource) => resource.resourceId),
};

export const isPublicHighSchoolResource = (
  resource: HighSchoolFormalResource,
): boolean =>
  resource.categoryId === HIGH_SCHOOL_INDEX_META.formalCategoryId &&
  resource.reviewStatus === "VERIFIED" &&
  resource.publicationStatus === "published" &&
  HIGH_SCHOOL_COURSE_INDEX.publishedResourceIds.includes(resource.resourceId);

export const getHighSchoolCoursesByGrade = (grade: HighSchoolGrade) =>
  HIGH_SCHOOL_COURSE_INDEX.courses.filter((course) => course.grade === grade);

export const getHighSchoolCourse = (
  grade: HighSchoolGrade,
  subject: HighSchoolSubject,
) =>
  HIGH_SCHOOL_COURSE_INDEX.courses.find(
    (course) => course.grade === grade && course.subject === subject,
  );

export const getPublishedResourcesForCourse = (courseId: string) =>
  HIGH_SCHOOL_COURSE_INDEX.formalResources.filter(
    (resource) =>
      resource.parentCourseId === courseId && isPublicHighSchoolResource(resource),
  );

export const getPublishedResourcesForSubject = (
  grade: HighSchoolGrade,
  subject: HighSchoolSubject,
) => {
  const course = getHighSchoolCourse(grade, subject);
  return course ? getPublishedResourcesForCourse(course.courseId) : [];
};



